from flask import request
from flask_login import logout_user, current_user

from const.path import BUILD_PATH
from const.datasources import DS_PATH
from env import QuerybookSettings
from lib.utils.import_helper import import_module_with_default


auth = None
login_config = None


def init_app(flask_app):
    load_auth()

    global auth
    auth.init_app(flask_app)

    @flask_app.before_request
    def check_auth():
        ignore_paths = ["/ping/"] + getattr(auth, "ignore_paths", [])

        if request.path in ignore_paths:
            return
        # API LOGIC and Static File are handled differently
        if request.path.startswith(DS_PATH) or request.path.startswith(BUILD_PATH):
            return
        if not current_user.is_authenticated:
            return auth.login(request)

    check_auth  # PYLINT :(


def load_auth():
    global auth
    auth = import_module_with_default(QuerybookSettings.AUTH_BACKEND)
    get_login_config()


def logout():
    logout_user()


def get_login_config():
    from app.datasource import register

    global auth
    global login_config
    if login_config is None:
        oauth_url = ""
        has_login = hasattr(auth, "login_user_endpoint")
        has_signup = hasattr(auth, "signup_user_endpoint")
        has_oauth_url = hasattr(auth, "oauth_authorization_url")

        if has_login:
            register(
                "/login/", methods=["POST"], require_auth=False, api_logging=False
            )(auth.login_user_endpoint)

        if has_signup:
            register(
                "/signup/", methods=["POST"], require_auth=False, api_logging=False
            )(auth.signup_user_endpoint)

        if has_oauth_url:
            oauth_url = auth.oauth_authorization_url()

        login_config = {
            "has_login": has_login,
            "has_signup": has_signup,
            "oauth_url": oauth_url,
        }
    return login_config

import requests

from app.auth.oauth_auth import OAuthLoginManager, OAUTH_CALLBACK_PATH
from env import QuerybookSettings, get_env_config
from .utils import AuthenticationError


class AzureLoginManager(OAuthLoginManager):
    @property
    def oauth_config(self):
        return {
            "callback_url": "{}{}".format(
                QuerybookSettings.PUBLIC_URL, OAUTH_CALLBACK_PATH
            ),
            "client_id": QuerybookSettings.OAUTH_CLIENT_ID,
            "client_secret": QuerybookSettings.OAUTH_CLIENT_SECRET,
            "authorization_url": "https://login.microsoftonline.com/{}/oauth2/v2.0/authorize".format(
                get_env_config("AZURE_TENANT_ID")
            ),
            "token_url": "https://login.microsoftonline.com/{}/oauth2/v2.0/token".format(
                get_env_config("AZURE_TENANT_ID")
            ),
            "profile_url": "https://graph.microsoft.com/oidc/userinfo",
            "scope": ["openid", "profile", "email", "User.Read"],
        }

    def _get_user_profile(self, access_token):
        resp = requests.get(
            self.oauth_config["profile_url"],
            headers={"Authorization": "Bearer {}".format(access_token)},
        )
        if not resp or resp.status_code != 200:
            raise AuthenticationError(
                "Failed to fetch user profile, status ({0})".format(
                    resp.status if resp else "None"
                )
            )
        return self._parse_user_profile(resp.json())

    def _parse_user_profile(self, user_info):
        return user_info["name"], user_info["email"]


login_manager = AzureLoginManager()

ignore_paths = [OAUTH_CALLBACK_PATH]


def init_app(app):
    login_manager.init_app(app)


def login(request):
    return login_manager.login(request)

import os
import requests
from app.auth.oauth_auth import OAuthLoginManager, OAUTH_CALLBACK_PATH
from env import QuerybookSettings

from .utils import AuthenticationError

# Relevant github issue https://github.com/singingwolfboy/flask-dance/issues/235
os.environ["OAUTHLIB_RELAX_TOKEN_SCOPE"] = "1"


class GitHubLoginManager(OAuthLoginManager):
    @property
    def oauth_config(self):
        return {
            "callback_url": "{}{}".format(
                QuerybookSettings.PUBLIC_URL, OAUTH_CALLBACK_PATH
            ),
            "client_id": QuerybookSettings.OAUTH_CLIENT_ID,
            "client_secret": QuerybookSettings.OAUTH_CLIENT_SECRET,
            "authorization_url": "https://github.com/login/oauth/authorize",
            "token_url": "https://github.com/login/oauth/access_token",
            "profile_url": "https://api.github.com/user",
            "scope": "user:email",
        }

    def _get_user_profile(self, access_token):
        resp = requests.get(
            self.oauth_config["profile_url"],
            headers={"Authorization": "Bearer {}".format(access_token)},
        )
        if not resp or resp.status_code != 200:
            raise AuthenticationError(
                "Failed to fetch user profile, status ({0})".format(
                    resp.status if resp else "None"
                )
            )
        return self._parse_user_profile(resp)

    def _parse_user_profile(self, resp):
        user = resp.json()

        email = user["email"]
        username = user["login"]
        return username, email


login_manager = GitHubLoginManager()
ignore_paths = [OAUTH_CALLBACK_PATH]


def init_app(app):
    login_manager.init_app(app)


def login(request):
    return login_manager.login(request)

from app.auth.oauth_auth import OAuthLoginManager, OAUTH_CALLBACK_PATH
from env import QuerybookSettings
from clients.google_client import get_google_oauth_config


class GoogleLoginManager(OAuthLoginManager):
    @property
    def oauth_config(self):
        google_config = get_google_oauth_config()

        return {
            "callback_url": "{}{}".format(
                QuerybookSettings.PUBLIC_URL, OAUTH_CALLBACK_PATH
            ),
            "client_id": QuerybookSettings.OAUTH_CLIENT_ID,
            "client_secret": QuerybookSettings.OAUTH_CLIENT_SECRET,
            "authorization_url": google_config["authorization_endpoint"],
            "token_url": google_config["token_endpoint"],
            "profile_url": google_config["userinfo_endpoint"],
            "scope": [
                "https://www.googleapis.com/auth/userinfo.email",
                "openid",
                "https://www.googleapis.com/auth/userinfo.profile",
            ],
        }

    def _parse_user_profile(self, resp):
        user = resp.json()
        username = user["email"].split("@")[0]
        return username, user["email"]


login_manager = GoogleLoginManager()

ignore_paths = [OAUTH_CALLBACK_PATH]


def init_app(app):
    login_manager.init_app(app)


def login(request):
    return login_manager.login(request)

from contextlib import contextmanager
from dataclasses import dataclass
from typing import Dict, Iterator, List, Optional, Tuple, Union

import ldap
import flask_login
import re
from ldap.ldapobject import SimpleLDAPObject

from flask_login import current_user
from env import QuerybookSettings
from app.db import with_session, DBSession
from .utils import AuthenticationError, AuthUser, QuerybookLoginManager
from lib.logger import get_logger
from logic.user import (
    get_user_by_name,
    create_user,
)
from models.user import User

LOG = get_logger(__file__)

login_manager = QuerybookLoginManager()


class LDAPAuthErrors:
    BAD_CREDENTIALS = "Bad credentials"
    UNAUTHORIZED = "Unauthorized"


@dataclass
class LDAPUserInfo:
    LDAP_ATTRS = ["cn", "givenName", "mail", "sn"]

    cn: Optional[str] = None
    dn: Optional[str] = None
    email: Optional[str] = None
    first_name: Optional[str] = None
    last_name: Optional[str] = None

    @property
    def full_name(self) -> str:
        full_name = " ".join(filter(bool, [self.first_name, self.last_name]))
        return full_name if full_name else self.cn


def _sanitize_ldap_search_results(
    search_results: List[Tuple],
) -> Optional[Tuple[str, Dict]]:
    # Remove any search referrals from results
    cleared_results = [
        (dn, attrs)
        for dn, attrs in search_results
        if dn is not None and isinstance(attrs, dict)
    ]
    n_found = len(cleared_results)
    if n_found != 1:
        if n_found > 1:
            LOG.warning(f"LDAP search returned {n_found} results")
        return None
    return cleared_results[0]


def _get_ldap_filter() -> str:
    search_filter = (
        QuerybookSettings.LDAP_FILTER
        if QuerybookSettings.LDAP_USE_BIND_USER and QuerybookSettings.LDAP_FILTER
        else "(objectClass=*)"
    )

    if QuerybookSettings.LDAP_FILTER and not QuerybookSettings.LDAP_USE_BIND_USER:
        LOG.warning(
            "LDAP_FILTER is going to be ignored when LDAP_USE_BIND_USER is not True"
        )

    if search_filter and not re.match("\\(.*\\)", search_filter):
        search_filter = f"({search_filter})"

    return search_filter


def _parse_value(value: Union[bytes, str, List[Union[bytes, str]]]) -> str:
    if isinstance(value, List):
        value = value[0]
    if isinstance(value, bytes):
        return value.decode("utf-8")
    return value


def _parse_user_info(ldap_user_info: Tuple[str, Dict]) -> LDAPUserInfo:
    try:
        user_info = ldap_user_info[1]
        return LDAPUserInfo(
            cn=_parse_value(user_info["cn"]),
            dn=ldap_user_info[0],
            email=_parse_value(user_info["mail"]),
            first_name=_parse_value(user_info["givenName"]),
            last_name=_parse_value(user_info["sn"]),
        )

    except (IndexError, NameError):
        LOG.error(f"Failed to parse UserInfo from: {ldap_user_info}")
        raise AuthenticationError("Failed to parse user information")


def ldap_authenticate(ldap_conn: SimpleLDAPObject, user_dn: str, password: str):
    """Validates/binds the provided dn/password with the LDAP sever."""
    try:
        LOG.debug(f"LDAP bind TRY with username: '{user_dn}'")
        ldap_conn.simple_bind_s(who=user_dn, cred=password)
        LOG.debug(f"LDAP bind SUCCESS with username: '{user_dn}'")
        return True
    except ldap.INVALID_CREDENTIALS:
        return False


@with_session
def login_user(username: str, email: str, full_name: str, session=None):
    # Case-insensitive search of the user for backward compatibility.
    # Because it was possible to create e.g. uppercase usernames before.
    user = get_user_by_name(username, case_sensitive=False, session=session)
    if not user:
        # Usernames of new LDAP users are lowered in the DB in order to prevent storing
        # randomly formatted strings from the user input.
        user = create_user(
            username=username.lower(), fullname=full_name, email=email, session=session
        )
    return user


def search_user_by_uid(
    ldap_conn: SimpleLDAPObject,
    uid: str = None,
    attrs: Optional[List[str]] = None,
    apply_filter: bool = False,
) -> Optional[Tuple[str, Dict]]:
    search_filter = (
        f"(&({QuerybookSettings.LDAP_UID_FIELD}={uid})"
        + (_get_ldap_filter() if apply_filter else "(objectClass=*)")
        + ")"
    )
    try:
        raw_search_result = ldap_conn.search_s(
            base=QuerybookSettings.LDAP_SEARCH,
            scope=ldap.SCOPE_SUBTREE,
            filterstr=search_filter,
            attrlist=attrs,
        )
    except ldap.NO_SUCH_OBJECT:
        return None
    return _sanitize_ldap_search_results(raw_search_result)


def search_user_by_dn(
    ldap_conn: SimpleLDAPObject,
    user_dn: str = None,
    attrs: Optional[List[str]] = None,
    apply_filter: bool = False,
) -> Optional[Tuple[str, Dict]]:
    try:
        filter_str = _get_ldap_filter() if apply_filter else "(objectClass=*)"
        raw_search_result = ldap_conn.search_s(
            base=user_dn,
            scope=ldap.SCOPE_SUBTREE,
            filterstr=filter_str,
            attrlist=attrs,
        )
    except ldap.NO_SUCH_OBJECT:
        return None
    return _sanitize_ldap_search_results(raw_search_result)


def get_transformed_username(
    ldap_conn: SimpleLDAPObject, username: str
) -> Tuple[str, str]:
    # Case when there is a username in form of DN
    if re.match(r"^\w+=.+", username):
        dn = username
        if QuerybookSettings.LDAP_USE_BIND_USER:
            search_result = search_user_by_dn(
                ldap_conn, user_dn=dn, attrs=[QuerybookSettings.LDAP_UID_FIELD]
            )
            if not search_result:
                # In case when provided DN wasn't found in LDAP
                raise AuthenticationError(LDAPAuthErrors.BAD_CREDENTIALS)
            username = _parse_value(search_result[1][QuerybookSettings.LDAP_UID_FIELD])
        else:
            match = re.match(
                QuerybookSettings.LDAP_USER_DN.replace("{}", "(.+?)"), username
            )
            if not match:
                raise ValueError(
                    f"Username in form of LDAP DN has to follow '{QuerybookSettings.LDAP_USER_DN}' pattern"
                )
            username = match.group(1)
    # Username in form of UID
    else:
        if QuerybookSettings.LDAP_USE_BIND_USER:
            search_result = search_user_by_uid(ldap_conn, uid=username)
            if not search_result:
                # In case when provided UID wasn't found in LDAP
                raise AuthenticationError(LDAPAuthErrors.BAD_CREDENTIALS)
            dn = search_result[0]
        else:
            dn = QuerybookSettings.LDAP_USER_DN.format(username)

    return username, dn


@contextmanager
def ldap_connection() -> Iterator[SimpleLDAPObject]:
    try:
        conn = ldap.initialize(QuerybookSettings.LDAP_CONN, trace_level=0)
        conn.set_option(ldap.OPT_REFERRALS, 0)
    except ldap.LDAPError as ldap_error:
        raise ConnectionError("Failed to create LDAP connection") from ldap_error

    if QuerybookSettings.LDAP_USE_TLS:
        try:
            conn.start_tls_s()
        except ldap.CONNECT_ERROR as connect_error:
            raise ConnectionError(
                "Failed to create LDAP TLS connection"
            ) from connect_error

    try:
        yield conn
    finally:
        conn.unbind_s()


def authenticate_user_by_bind_connection(
    user_dn: str,
    password: str,
    bind_conn: SimpleLDAPObject,
    user_conn: SimpleLDAPObject,
) -> LDAPUserInfo:
    # Try to connect with user credentials now
    if not ldap_authenticate(user_conn, user_dn=user_dn, password=password):
        raise AuthenticationError(LDAPAuthErrors.BAD_CREDENTIALS)

    # Get information about the session user using the bind user.
    # The filter is applied, so no results means the user isn't allowed.
    user_info_search = search_user_by_dn(
        bind_conn, user_dn=user_dn, attrs=LDAPUserInfo.LDAP_ATTRS, apply_filter=True
    )
    if not user_info_search:
        raise AuthenticationError(LDAPAuthErrors.UNAUTHORIZED)

    return _parse_user_info(user_info_search)


def authenticate_user_by_direct_connection(
    user_dn: str, password: str, user_conn: SimpleLDAPObject
) -> LDAPUserInfo:
    # Try to do direct authentication with the session user
    if not ldap_authenticate(user_conn, user_dn=user_dn, password=password):
        raise AuthenticationError(LDAPAuthErrors.BAD_CREDENTIALS)

    # In case of direct login, ldap_search may not be allowed for all users,
    # therefore it's not possible to obtain user details, but user should be allowed.
    user_info_search = search_user_by_dn(
        user_conn, user_dn=user_dn, attrs=LDAPUserInfo.LDAP_ATTRS
    )
    return (
        _parse_user_info(user_info_search)
        if user_info_search
        else LDAPUserInfo(dn=user_dn)
    )


def login_user_endpoint(username, password) -> Optional[User]:
    if current_user.is_authenticated:
        return

    if not username or not password:
        raise AuthenticationError("Missing username or password")

    if QuerybookSettings.LDAP_USE_BIND_USER:
        with ldap_connection() as bind_conn:
            # Try to make connection with the bind user first
            if not ldap_authenticate(
                bind_conn,
                user_dn=QuerybookSettings.LDAP_BIND_USER,
                password=QuerybookSettings.LDAP_BIND_PASSWORD,
            ):
                raise ConnectionError(
                    "Failed to establish LDAP connection for bind user"
                )

            processed_username, user_dn = get_transformed_username(bind_conn, username)

            with ldap_connection() as user_conn:
                ldap_user_info = authenticate_user_by_bind_connection(
                    user_dn=user_dn,
                    password=password,
                    bind_conn=bind_conn,
                    user_conn=user_conn,
                )
    else:
        with ldap_connection() as user_conn:
            processed_username, user_dn = get_transformed_username(user_conn, username)

            ldap_user_info = authenticate_user_by_direct_connection(
                user_dn=user_dn, password=password, user_conn=user_conn
            )

    with DBSession() as session:
        db_user = login_user(
            username=processed_username,
            email=ldap_user_info.email,
            full_name=ldap_user_info.full_name,
            session=session,
        )
        flask_login.login_user(AuthUser(db_user))
        return db_user


def init_app(app) -> None:
    login_manager.init_app(app)


def login(_) -> None:
    # The webapp will handle the UI for logging in
    pass

import certifi
import requests


from flask import request, session as flask_session, redirect
import flask_login
from requests_oauthlib import OAuth2Session

from app.db import with_session, DBSession
from env import QuerybookSettings
from lib.logger import get_logger
from logic.user import (
    get_user_by_name,
    create_user,
)
from .utils import (
    AuthenticationError,
    AuthUser,
    abort_unauthorized,
    QuerybookLoginManager,
)

LOG = get_logger(__file__)

OAUTH_CALLBACK_PATH = "/oauth2callback"


class OAuthLoginManager(object):
    def __init__(self):
        self.login_manager = QuerybookLoginManager()
        self.flask_app = None

    @property
    def oauth_session(self):
        oauth_config = self.oauth_config
        return OAuth2Session(
            oauth_config["client_id"],
            scope=oauth_config["scope"],
            redirect_uri=oauth_config["callback_url"],
        )

    @property
    def oauth_config(self):
        return {
            "callback_url": "{}{}".format(
                QuerybookSettings.PUBLIC_URL, OAUTH_CALLBACK_PATH
            ),
            "client_id": QuerybookSettings.OAUTH_CLIENT_ID,
            "client_secret": QuerybookSettings.OAUTH_CLIENT_SECRET,
            "authorization_url": QuerybookSettings.OAUTH_AUTHORIZATION_URL,
            "token_url": QuerybookSettings.OAUTH_TOKEN_URL,
            "profile_url": QuerybookSettings.OAUTH_USER_PROFILE,
            "scope": "user",
        }

    def init_app(self, flask_app):
        self.flask_app = flask_app

        self.login_manager.init_app(self.flask_app)
        self.flask_app.add_url_rule(
            OAUTH_CALLBACK_PATH, "oauth_callback", self.oauth_callback
        )

    def login(self, request):
        oauth_url, _ = self._get_authn_url()
        flask_session["next"] = request.path
        return redirect(oauth_url)

    def _get_authn_url(self):
        return self.oauth_session.authorization_url(
            self.oauth_config["authorization_url"]
        )

    def oauth_callback(self):
        LOG.debug("Handling Oauth callback...")

        if request.args.get("error"):
            return f"<h1>Error: {request.args.get('error')}</h1>"

        code = request.args.get("code")
        try:
            access_token = self._fetch_access_token(code)
            username, email = self._get_user_profile(access_token)
            with DBSession() as session:
                flask_login.login_user(
                    AuthUser(self.login_user(username, email, session=session))
                )
        except AuthenticationError as e:
            LOG.error("Failed authenticate oauth user", e)
            abort_unauthorized()

        next_url = QuerybookSettings.PUBLIC_URL
        if "next" in flask_session:
            next_url = flask_session["next"]
            del flask_session["next"]

        return redirect(next_url)

    def _fetch_access_token(self, code):
        resp = self.oauth_session.fetch_token(
            token_url=self.oauth_config["token_url"],
            client_id=self.oauth_config["client_id"],
            code=code,
            client_secret=self.oauth_config["client_secret"],
            cert=certifi.where(),
        )
        if resp is None:
            raise AuthenticationError("Null response, denying access.")
        return resp["access_token"]

    def _get_user_profile(self, access_token):
        resp = requests.get(
            self.oauth_config["profile_url"],
            headers={"Authorization": "Bearer {}".format(access_token)},
        )
        if not resp or resp.status_code != 200:
            raise AuthenticationError(
                "Failed to fetch user profile, status ({0})".format(
                    resp.status if resp else "None"
                )
            )
        return self._parse_user_profile(resp)

    def _parse_user_profile(self, profile_response):
        user = profile_response.json()["user"]
        return user["username"], user["email"]

    @with_session
    def login_user(self, username, email, session=None):
        if not username:
            raise AuthenticationError("Username must not be empty!")

        user = get_user_by_name(username, session=session)
        if not user:
            user = create_user(
                username=username, fullname=username, email=email, session=session
            )
        return user


login_manager = OAuthLoginManager()

ignore_paths = [OAUTH_CALLBACK_PATH]


def init_app(app):
    login_manager.init_app(app)


def login(request):
    return login_manager.login(request)


def oauth_authorization_url():
    return login_manager._get_authn_url()

import certifi
import requests
import flask_login

from app.auth.oauth_auth import OAuthLoginManager, OAUTH_CALLBACK_PATH
from app.db import with_session, DBSession
from env import QuerybookSettings, get_env_config
from flask import request, session as flask_session, redirect
from lib.logger import get_logger
from lib.utils.decorators import in_mem_memoized
from logic.user import (
    get_user_by_name,
    create_user,
)
from .utils import AuthenticationError, abort_unauthorized, AuthUser

LOG = get_logger(__file__)


class NoopAuth(requests.auth.AuthBase):
    """
    This auth doesn't do anything.
    It only used to override oauthlib's behavior.
    """

    def __call__(self, r):
        return r


class OktaLoginManager(OAuthLoginManager):
    def get_okta_urls(self):
        okta_base_url = get_env_config("OKTA_BASE_URL")
        authorization_url = f"{okta_base_url}/v1/authorize"
        token_url = f"{okta_base_url}/v1/token"
        profile_url = f"{okta_base_url}/v1/userinfo"
        return authorization_url, token_url, profile_url

    @property
    @in_mem_memoized()
    def oauth_config(self):
        authorization_url, token_url, profile_url = self.get_okta_urls()

        return {
            "callback_url": "{}{}".format(
                QuerybookSettings.PUBLIC_URL, OAUTH_CALLBACK_PATH
            ),
            "client_id": QuerybookSettings.OAUTH_CLIENT_ID,
            "client_secret": QuerybookSettings.OAUTH_CLIENT_SECRET,
            "authorization_url": authorization_url,
            "token_url": token_url,
            "profile_url": profile_url,
            "scope": ["openid", "email", "profile"],
        }

    def _fetch_access_token(self, code):
        resp = self.oauth_session.fetch_token(
            token_url=self.oauth_config["token_url"],
            client_id=self.oauth_config["client_id"],
            code=code,
            client_secret=self.oauth_config["client_secret"],
            cert=certifi.where(),
            # This Authentication is needed because Okta would throw error
            # about passing client_secret and client_id in request.header
            # which is the default behavior of oauthlib
            auth=NoopAuth(),
        )
        if resp is None:
            raise AuthenticationError("Null response, denying access.")
        return resp["access_token"]

    def _get_user_profile(self, access_token):
        resp = requests.get(
            self.oauth_config["profile_url"],
            headers={"Authorization": "Bearer {}".format(access_token)},
        )
        if not resp or resp.status_code != 200:
            raise AuthenticationError(
                "Failed to fetch user profile, status ({0})".format(
                    resp.status if resp else "None"
                )
            )
        return self._parse_user_profile(resp)

    def oauth_callback(self):
        LOG.debug("Handling Oauth callback...")

        if request.args.get("error"):
            return f"<h1>Error: {request.args.get('error')}</h1>"

        code = request.args.get("code")
        try:
            access_token = self._fetch_access_token(code)
            username, email, fullname = self._get_user_profile(access_token)
            with DBSession() as session:
                flask_login.login_user(
                    AuthUser(
                        self.login_user(username, email, fullname, session=session)
                    )
                )
        except AuthenticationError as e:
            LOG.error("Failed authenticate oauth user", e)
            abort_unauthorized()

        next_url = QuerybookSettings.PUBLIC_URL
        if "next" in flask_session:
            next_url = flask_session["next"]
            del flask_session["next"]

        return redirect(next_url)

    def _parse_user_profile(self, resp):
        user = resp.json()
        username = user["email"].split("@")[0]
        return username, user["email"], user["name"]

    @with_session
    def login_user(self, username, email, fullname, session=None):
        if not username:
            raise AuthenticationError("Username must not be empty!")

        user = get_user_by_name(username, session=session)
        if not user:
            user = create_user(
                username=username, fullname=fullname, email=email, session=session
            )
        return user


login_manager = OktaLoginManager()

ignore_paths = [OAUTH_CALLBACK_PATH]


def init_app(app):
    login_manager.init_app(app)


def login(request):
    return login_manager.login(request)

